export function dataApi(o: DataApiOptions): Db {
  // maxAttempts 1: the SDK must not retry on its own, since a blind retry of a write can apply it twice.
  const client: Client = o.client ?? new RDSDataClient({ maxAttempts: 1 });
  const budget = o.budgetMs ?? defaultBudgetMs;
  const target = { resourceArn: o.resourceArn, secretArn: o.secretArn };

  async function send<T>(deadline: number, command: unknown): Promise<T> {
    for (let wait = 500; ; wait = Math.min(wait * 2, 4_000)) {
      const left = deadline - Date.now();
      if (left <= 0) throw new Unavailable(startingUp, 5);
      try {
        return (await client.send(command, { abortSignal: AbortSignal.timeout(left) })) as T;
      } catch (e) {
        if (resuming(e) && Date.now() + wait < deadline) {
          await sleep(wait);
          continue;
        }
        if (resuming(e) || aborted(e)) throw new Unavailable(startingUp, 5);
        if (tooLarge(e)) throw new ResponseTooLarge((e as Error).message);
        throw e;
      }
    }
  }

  const execute = (deadline: number, text: string, params: readonly Param[], transactionId?: string) =>
    send<ExecuteStatementCommandOutput>(
      deadline,
      new ExecuteStatementCommand({
        ...target,
        database: o.database,
        transactionId,
        sql: text.replace(/\$(\d+)/g, ":p$1"),
        parameters: params.map(toParam),
        includeResultMetadata: true,
      }),
    ).then(toRows);

  async function commit(deadline: number, transactionId: string) {
    try {
      await client.send(new CommitTransactionCommand({ ...target, transactionId }), {
        abortSignal: AbortSignal.timeout(Math.max(deadline - Date.now(), 0) + commitGraceMs),
      });
    } catch (e) {
      // The statement errors Postgres raises at commit mean it rolled back; anything else leaves the outcome unknown.
      if (errorName(e) === "DatabaseErrorException") throw e;
      throw new Unavailable(unknownOutcome);
    }
  }

  const rollback = (transactionId: string) =>
    client
      .send(new RollbackTransactionCommand({ ...target, transactionId }), { abortSignal: AbortSignal.timeout(2_000) })
      .catch(() => undefined);

  const noNesting = () => {
    throw new Error("nested transactions are not supported");
  };

  return {
    driver: "data-api",
    query: (text, params = []) => execute(Date.now() + budget, text, params),
    async begin(fn) {
      const deadline = Date.now() + budget;
      const { transactionId } = await send<{ transactionId?: string }>(
        deadline,
        new BeginTransactionCommand({ ...target, database: o.database }),
      );
      if (!transactionId) throw new Error("the Data API returned no transaction id");
      const tx: Db = {
        driver: "data-api",
        query: (text, params = []) => execute(deadline, text, params, transactionId),
        begin: noNesting,
      };
      let result: Awaited<ReturnType<typeof fn>>;
      try {
        result = await fn(tx);
      } catch (e) {
        await rollback(transactionId);
        throw e;
      }
      await commit(deadline, transactionId);
      return result;
    },
  };
}
